 static string folder,kind;static bool active;static int frame,stage,shotIndex;static float stageAt,warningAt,firstFireAt,deathAt,initialHealth,maxObservedStep;static double beganWall,pauseWall,settleWall;static int pauseStage;static string pausedState,pauseLabel;static readonly HashSet<string> paused=new(),captures=new();static readonly HashSet<int> knownShots=new();static readonly Dictionary<int,float> births=new();static readonly List<object> checks=new(),events=new();static readonly List<string> errors=new();static int failures;static Vector3[] queueOrigins;static int timelineIndex;static Vector3 savedActorPosition;
 static string Json(object x)=>(string)AppDomain.CurrentDomain.GetAssemblies().First(a=>a.GetName().Name=="Newtonsoft.Json").GetType("Newtonsoft.Json.JsonConvert").GetMethod("SerializeObject",new[]{typeof(object)}).Invoke(null,new[]{x});
 static void Set(object o,string n,object v)=>o.GetType().GetField("<"+n+">k__BackingField",F).SetValue(o,v);
